mapper.insert:
/* RecipeMapper.insertRecipeInfo : 레시피 정보 등록 */
INSERT INTO RECIPE (
    RECIPE_ID, RECIPE_TTL, DISH_NM, RECIPE_CN, COOKING_TIME, RECIPE_DIFFICULT_CD,
    CATEGORY_CD, FILE_GRP_ID, RGTR_KEY, RECIPE_STATUS
) VALUES (
    #{recipeId}, #{recipeTtl}, #{dishNm}, #{recipeCn}, #{cookingTime}, #{recipeDifficultCd},
    #{categoryCd}, #{fileGrpId}, #{rgtrKey}, #{recipeStatus}
)

/* RecipeMapper.insertRecipeIngredient : 레시피 재료 정보 등록 */
INSERT INTO INGREDIENT (
    RECIPE_SEQ, INGRD_NM, INGRD_AMT, INGRD_UNT
) VALUES (
    #{recipeSeq}, #{ingrdNm}, #{ingrdAmt}, #{ingrdUnt}
)

/* RecipeMapper.insertRecipeStep : 레시피 단계 정보 등록 */
INSERT INTO RECIPE_STEP (
    RECIPE_SEQ, STEP_NO, STEP_CN, FILE_GRP_ID
) VALUES (
    #{recipeSeq}, #{stepNo}, #{stepCn}, #{fileGrpId}
)

mapper.select:
/* RecipeMapper.selectRecipeInfoList : 레시피 정보 목록 페이징 및 조건 조회 */
SELECT R.RECIPE_SEQ , R.RECIPE_ID , R.RECIPE_TTL , R.DISH_NM , R.RECIPE_CN , R.COOKING_TIME , R.RECIPE_DIFFICULT_CD , R.CATEGORY_CD , R.VIEW_CNT , (SELECT COUNT(*) FROM LIKES L WHERE L.TGT_SEQ = R.RECIPE_SEQ) AS LIKE_CNT , U.USER_NM AS WRITER_NAME , R.FILE_GRP_ID , R.REG_DT FROM RECIPE R INNER JOIN USERS U ON R.RGTR_KEY = U.USER_KEY AND U.DEL_YN = 'N' WHERE R.DEL_YN = 'N'
AND R.CATEGORY_CD = #{categoryCd}
AND R.RECIPE_DIFFICULT_CD = #{recipeDifficultCd}
AND ( R.RECIPE_TTL LIKE CONCAT('%', #{searchKeyword}, '%') OR R.DISH_NM LIKE CONCAT('%', #{searchKeyword}, '%') )
AND R.VIEW_CNT >= #{minViews}
AND (SELECT COUNT(*) FROM LIKES L WHERE L.TGT_SEQ = R.RECIPE_SEQ) >= #{minLikes}
AND R.REG_DT >= CURRENT_TIMESTAMP - INTERVAL '1 DAY'
AND R.REG_DT >= CURRENT_TIMESTAMP - INTERVAL '1 WEEK'
AND R.REG_DT >= CURRENT_TIMESTAMP - INTERVAL '1 MONTH'
ORDER BY R.REG_DT DESC

mapper.update:
/* RecipeMapper.updateRecipeInfo : 레시피 정보 수정 */
UPDATE RECIPE
SET RECIPE_TTL          = #{recipeTtl}
  , DISH_NM             = #{dishNm}
  , RECIPE_CN           = #{recipeCn}
  , COOKING_TIME        = #{cookingTime}
  , RECIPE_DIFFICULT_CD = #{recipeDifficultCd}
  , CATEGORY_CD         = #{categoryCd}
  , RECIPE_STATUS       = #{recipeStatus}
  , FILE_GRP_ID         = #{fileGrpId}
  , MDFCN_DT            = CURRENT_TIMESTAMP
WHERE RECIPE_SEQ = #{recipeSeq}

/* RecipeMapper.deleteRecipeIngredientList : 레시피 재료 정보 삭제 */
UPDATE INGREDIENT
SET DEL_YN = 'Y'
WHERE RECIPE_SEQ = #{recipeSeq}

/* RecipeMapper.deleteRecipeStepList : 레시피 단계 정보 삭제 */
UPDATE RECIPE_STEP
SET DEL_YN = 'Y'
WHERE RECIPE_SEQ = #{recipeSeq}

/* RecipeMapper.deleteRecipeInfo : 레시피 정보 삭제 */
UPDATE RECIPE
   SET DEL_YN   = 'Y'
     , MDFCN_DT = CURRENT_TIMESTAMP
 WHERE RECIPE_ID = #{recipeId}
